css:
.ccisim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2620;
    background:
        repeating-linear-gradient(0deg, rgba(43, 38, 32, 0.018) 0px, rgba(43, 38, 32, 0.018) 1px, transparent 1px, transparent 28px),
        linear-gradient(180deg, #f7f2e7 0%, #efe7d6 100%);
    border: 1px solid #d8ccb2;
    border-radius: 6px;
    box-shadow: inset 0 0 0 1px #fbf7ee;
}

.ccisim-container * {
    box-sizing: border-box;
}

.ccisim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #142a4c 0%, #1d3a63 55%, #234a78 100%);
    color: #f3ecda;
    border-radius: 6px;
    margin-bottom: 20px;
    border-top: 5px solid #e08a1e;
    border-bottom: 5px solid #1a7a4f;
    box-shadow: 0 10px 26px rgba(20, 42, 76, 0.28);
}

.ccisim-header h1 {
    margin: 10px 0 12px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.5rem;
    font-weight: 700;
    letter-spacing: 0.4px;
    color: #fbf6e8;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

.ccisim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #f3c277;
    background: rgba(224, 138, 30, 0.16);
    border: 1px solid rgba(224, 138, 30, 0.45);
    padding: 5px 14px;
    border-radius: 3px;
}

.ccisim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #d8e0ee;
}

.ccisim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.95rem;
    font-weight: 600;
    color: #5a4f3c;
    margin-bottom: 18px;
    padding: 8px 6px;
    border-bottom: 2px solid #d8ccb2;
}

.ccisim-period-counter #currentDay,
.ccisim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1d3a63;
    font-size: 1.05rem;
}

.ccisim-round-name {
    background: #1a7a4f;
    color: #f3ecda;
    padding: 3px 13px;
    border-radius: 3px;
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.4px;
    margin-left: 4px;
}

.ccisim-clock {
    margin-left: auto;
    font-size: 0.8rem;
    font-weight: 700;
    color: #9a3412;
    background: rgba(224, 138, 30, 0.14);
    border: 1px solid rgba(224, 138, 30, 0.4);
    padding: 4px 12px;
    border-radius: 3px;
}

.ccisim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.ccisim-status-card {
    background: #fffdf7;
    border-radius: 5px;
    padding: 16px 16px 14px;
    border: 1px solid #ddd0b6;
    border-left: 5px solid #1d3a63;
    box-shadow: 0 3px 10px rgba(43, 38, 32, 0.10);
}

.ccisim-card-welfare { border-left-color: #1a7a4f; }
.ccisim-card-rigour { border-left-color: #1d3a63; }
.ccisim-card-defence { border-left-color: #6b4ea8; }
.ccisim-card-error { border-left-color: #c2410c; }

.ccisim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a6e57;
}

.ccisim-value {
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.7rem;
    font-weight: 700;
    line-height: 1.05;
    margin: 6px 0 3px;
    color: #1d3a63;
    font-variant-numeric: tabular-nums;
}

.ccisim-card-welfare .ccisim-value { color: #15663f; }
.ccisim-card-rigour .ccisim-value { color: #1d3a63; }
.ccisim-card-defence .ccisim-value { color: #5b3f96; }
.ccisim-card-error .ccisim-value { color: #c2410c; }

.ccisim-sublabel {
    font-size: 0.75rem;
    color: #8a7d63;
    line-height: 1.35;
}

.ccisim-error-high { border-left-color: #b91c1c; background: #fff6f2; }
.ccisim-error-high .ccisim-value { color: #b91c1c; }
.ccisim-error-low { border-left-color: #1a7a4f; }
.ccisim-error-low .ccisim-value { color: #15663f; }

.ccisim-welfare-strong { background: #f4fbf5; }

.ccisim-clock-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #142a4c;
    border-radius: 5px;
    color: #e6ddc8;
    padding: 11px 18px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    letter-spacing: 0.3px;
}

.ccisim-clock-bar #clockBarDisplay {
    font-family: Georgia, serif;
    font-size: 1.15rem;
    color: #f3c277;
}

.ccisim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf7;
    border: 1px solid #ddd0b6;
    border-left: 5px solid #e08a1e;
    border-radius: 5px;
    padding: 18px 20px;
    margin-bottom: 16px;
    box-shadow: 0 3px 10px rgba(43, 38, 32, 0.08);
}

.ccisim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.ccisim-briefing-title {
    font-family: Georgia, 'Times New Roman', serif;
    font-weight: 700;
    font-size: 1.18rem;
    color: #1d3a63;
    margin-bottom: 7px;
}

.ccisim-briefing-text {
    font-size: 0.96rem;
    line-height: 1.6;
    color: #463e30;
}

.ccisim-briefing-text strong { color: #15663f; }
.ccisim-briefing-text em { color: #9a3412; font-style: italic; }

.ccisim-evidence {
    background: #f3ecda;
    border: 1px dashed #c4b48f;
    border-radius: 5px;
    padding: 14px 18px;
    margin-bottom: 16px;
}

.ccisim-evidence-title {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 800;
    color: #1d3a63;
    margin-bottom: 8px;
}

.ccisim-evidence-list {
    margin: 0;
    padding: 0;
    list-style: none;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 4px 22px;
}

.ccisim-evidence-list li {
    font-size: 0.86rem;
    color: #5a4f3c;
    padding: 3px 0;
    border-bottom: 1px dotted #d2c4a4;
}

.ccisim-evidence-list strong { color: #142a4c; }

.ccisim-controls {
    background: #fffdf7;
    border-radius: 5px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddd0b6;
    box-shadow: 0 3px 10px rgba(43, 38, 32, 0.08);
}

.ccisim-controls h3 {
    margin: 0 0 16px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.2rem;
    font-weight: 700;
    color: #1d3a63;
    border-bottom: 2px solid #e08a1e;
    padding-bottom: 8px;
}

.ccisim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a3326;
    margin: 16px 0 6px;
}

.ccisim-container select,
.ccisim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c4b48f;
    border-radius: 4px;
    font-size: 0.92rem;
    background-color: #fffdf7;
    color: #2b2620;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.ccisim-container select:focus,
.ccisim-container input[type="number"]:focus {
    outline: none;
    border-color: #1d3a63;
    box-shadow: 0 0 0 3px rgba(29, 58, 99, 0.16);
}

.ccisim-container select option {
    background-color: #fffdf7;
    color: #2b2620;
}

.ccisim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1a7a4f;
}

.ccisim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a4f3c;
    margin-top: 4px;
}

.ccisim-range-readout span:nth-child(2) {
    color: #15663f;
    font-weight: 800;
    font-size: 1.02rem;
}

.ccisim-hint {
    font-size: 0.8rem;
    color: #8a7d63;
    margin-top: 6px;
    line-height: 1.45;
    font-style: italic;
}

.ccisim-container .btn {
    margin-top: 18px;
    font-weight: 700;
    letter-spacing: 0.3px;
}

.ccisim-container .btn-primary {
    background: linear-gradient(135deg, #15663f 0%, #1a7a4f 100%);
    border: none;
    color: #f7f2e7;
    padding: 11px 28px;
    border-radius: 4px;
    box-shadow: 0 6px 16px rgba(21, 102, 63, 0.32);
}

.ccisim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.ccisim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c4b48f;
    color: #6b5f48;
    background: transparent;
}

.ccisim-coach {
    background: linear-gradient(160deg, #142a4c 0%, #1d3a63 100%);
    color: #e6ddc8;
    border-radius: 5px;
    border-left: 5px solid #e08a1e;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 42, 76, 0.24);
}

.ccisim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #f3c277;
    margin-bottom: 8px;
}

.ccisim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #dfe5f0;
}

.ccisim-coach-body strong { color: #f3c277; }
.ccisim-coach-body em { color: #8fd3b0; font-style: italic; }

.ccisim-history,
.ccisim-chart {
    background: #fffdf7;
    border-radius: 5px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddd0b6;
    box-shadow: 0 3px 10px rgba(43, 38, 32, 0.08);
}

.ccisim-history h3,
.ccisim-chart h3 {
    margin: 0 0 14px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.16rem;
    font-weight: 700;
    color: #1d3a63;
}

.ccisim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #463e30;
    border-collapse: collapse;
}

.ccisim-container table#usfHistoryTable th {
    background: #142a4c;
    color: #f3c277;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.5px;
    padding: 9px 10px;
    text-align: left;
}

.ccisim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e4dac3;
    color: #4a4234;
}

.ccisim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f2e7;
}

.ccisim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .ccisim-container {
        padding: 14px;
    }
    .ccisim-header h1 {
        font-size: 1.8rem;
    }
    .ccisim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .ccisim-value {
        font-size: 2.1rem;
    }
    .ccisim-clock {
        margin-left: 0;
    }
    .ccisim-period-counter {
        font-size: 0.86rem;
    }
    .ccisim-clock-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .ccisim-evidence-list {
        grid-template-columns: 1fr;
    }
    .ccisim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, ccisim) ---- */
.ccisim-completion { padding: 8px 4px 4px; }
.ccisim-cm-head { text-align: center; margin-bottom: 16px; }
.ccisim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #7a5ea8; }
.ccisim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #9c86bf; }
.ccisim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #2f2a3a; }
.ccisim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.ccisim-cm-yes { background: rgba(90,140,70,0.15); color: #4a7a2f; border: 1px solid rgba(90,140,70,0.5); }
.ccisim-cm-no { background: rgba(176,66,50,0.12); color: #a53f2c; border: 1px solid rgba(176,66,50,0.45); }
.ccisim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.ccisim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(122,94,168,0.08); border: 1px solid rgba(122,94,168,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.ccisim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #6a4f97; }
.ccisim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #6f6880; text-transform: uppercase; letter-spacing: 0.03em; }
.ccisim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #2f2a3a; }
.ccisim-cm-insights { margin: 0; padding-left: 20px; }
.ccisim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #3d374a; }

