(function() {
    'use strict';

    class MergerAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Merger Under Scrutiny`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (CCI / Aarav–Sundara).
            this.DEAL_VALUE = 14200;        // ₹14,200 crore all-cash
            this.SYNERGY_CLAIM = 900;       // ₹900 crore/yr claimed synergies
            this.HHI_PRE = 1950;            // national sunflower-oil pre-merger HHI
            this.HHI_POST = 2920;           // post-merger HHI
            this.HHI_DELTA = 970;           // +970 delta
            this.WELFARE_LOSS_MID = 2000;   // ₹ crore/yr midpoint pre-remedy welfare loss
            this.STATUTORY_LIMIT = 210;     // 210 working-day outer limit
            this.CANDIDATE_MARKETS = 4;     // national + 3 states all breach the screen

            // Concept truths (the defensible path).
            this.TRUE_PRODUCT = `narrow`;
            this.TRUE_GEO = `state`;
            this.TRUE_SSNIP = `run`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    welfare: 40,            // consumer-welfare protection (0–100)
                    rigour: 25,             // evidence over assertion (0–100)
                    defence: 30,            // NCLAT appeal defensibility (0–100)
                    error: 50,             // Type I + Type II exposure (lower better)
                    daysUsed: 0,            // statutory working days consumed (of 210)
                    marketTested: false,    // did R1 run SSNIP on a narrow market?
                    creditedSynergy: 0,    // ₹ crore of synergy credited after the 3-part test
                    predictedRise: 0,      // % unilateral price rise estimated in R3
                    finalReco: ``,         // clear / block / remedy
                    welfareHistory: [40],
                    rigourHistory: [25],
                    defenceHistory: [30],
                    errorHistory: [50],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the parties' framing / the classic errors —
                // a click-through must not auto-win.
                state.decisions = {
                    product: `broad`,
                    geo: `national`,
                    ssnip: `accept`,
                    screen: `verdict`,
                    theory: `unilateral`,
                    markets: 2,
                    diversion: 40,
                    synergy: `full`,
                    passthrough: 40,
                    reco: `clear`,
                    remedy: `behavioural`,
                    error: `typeii`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pr = document.getElementById(`productInput`);
                const ge = document.getElementById(`geoInput`);
                const ss = document.getElementById(`ssnipInput`);
                if (pr) decisions.product = pr.value;
                if (ge) decisions.geo = ge.value;
                if (ss) decisions.ssnip = ss.value;
                if (!decisions.product || !decisions.geo || !decisions.ssnip) {
                    warn(`warn_r1_incomplete`); return false;
                }
            } else if (round === 2) {
                const sc = document.getElementById(`screenInput`);
                const th = document.getElementById(`theoryInput`);
                const mk = document.getElementById(`marketsInput`);
                if (sc) decisions.screen = sc.value;
                if (th) decisions.theory = th.value;
                if (mk) decisions.markets = parseInt(mk.value, 10);
                if (!Number.isFinite(decisions.markets) || decisions.markets < 0 || decisions.markets > this.CANDIDATE_MARKETS) {
                    warn(`warn_markets_range`); return false;
                }
            } else if (round === 3) {
                const dv = document.getElementById(`diversionInput`);
                const sy = document.getElementById(`synergyInput`);
                const pt = document.getElementById(`passthroughInput`);
                if (dv) decisions.diversion = parseInt(dv.value, 10);
                if (sy) decisions.synergy = sy.value;
                if (pt) decisions.passthrough = parseFloat(pt.value);
                if (!Number.isFinite(decisions.diversion) || decisions.diversion < 5 || decisions.diversion > 60) {
                    warn(`warn_diversion_range`); return false;
                }
                if (!Number.isFinite(decisions.passthrough) || decisions.passthrough < 0 || decisions.passthrough > 100) {
                    warn(`warn_passthrough_range`); return false;
                }
            } else if (round === 4) {
                const rc = document.getElementById(`recoInput`);
                const rm = document.getElementById(`remedyInput`);
                const er = document.getElementById(`errorInput`);
                const cv = document.getElementById(`convictionInput`);
                if (rc) decisions.reco = rc.value;
                if (rm) decisions.remedy = rm.value;
                if (er) decisions.error = er.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
                if (decisions.reco === `remedy` && decisions.remedy === `none`) {
                    warn(`warn_remedy_required`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let welfareDelta = 0, rigourDelta = 0, defenceDelta = 0, errorDelta = 0, days = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Common Error 1: accepting the parties' broad market without testing it.
                days = 20;

                // PRODUCT market width.
                switch (d.product) {
                    case `narrow`: rigourDelta += 10; defenceDelta += 8; break;
                    case `broad`: rigourDelta -= 8; defenceDelta -= 6; errorDelta += 10; coachKey = `coach_r1_broad`; break;
                    case `single`: rigourDelta -= 4; defenceDelta -= 8; errorDelta += 6; coachKey = `coach_r1_single`; break;
                }

                // GEOGRAPHIC market.
                switch (d.geo) {
                    case `state`: rigourDelta += 8; defenceDelta += 6; break;
                    case `national`: rigourDelta -= 3; defenceDelta -= 3; errorDelta += 4; break;
                    case `global`: rigourDelta -= 8; defenceDelta -= 8; errorDelta += 8; coachKey = `coach_r1_global`; break;
                }

                // HOW the boundaries were fixed — the SSNIP test is the heart of R1.
                switch (d.ssnip) {
                    case `run`: rigourDelta += 14; defenceDelta += 12; ds.marketTested = true; break;
                    case `assume`: rigourDelta -= 4; defenceDelta -= 4; errorDelta += 5; break;
                    case `accept`: rigourDelta -= 10; defenceDelta -= 10; errorDelta += 12; coachKey = `coach_r1_accept`; break;
                }

                if (d.product === `narrow` && d.geo === `state` && d.ssnip === `run`) {
                    welfareDelta += 6; coachKey = `coach_r1_tested`;
                }

                summaryKey = (d.product === `narrow` && d.ssnip === `run`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Common Error 2: treating the HHI screen as the verdict (or dismissing it).
                days = 18;
                const tested = ds.marketTested;

                // Screen interpretation — the structural presumption is a TRIGGER, not a verdict.
                switch (d.screen) {
                    case `trigger`: rigourDelta += 10; defenceDelta += 12; errorDelta -= 6; break;
                    case `verdict`: rigourDelta -= 6; defenceDelta -= 12; errorDelta += 8; coachKey = `coach_r2_verdict`; break;
                    case `dismiss`: rigourDelta -= 8; defenceDelta -= 6; errorDelta += 10; coachKey = `coach_r2_dismiss`; break;
                }

                // Theory of harm — diversion drives unilateral; coordinated risk also present.
                switch (d.theory) {
                    case `both`: rigourDelta += 10; defenceDelta += 6; break;
                    case `unilateral`: rigourDelta += 4; defenceDelta += 2; break;
                    case `coordinated`: rigourDelta -= 2; defenceDelta -= 2; errorDelta += 3; coachKey = `coach_r2_coordinated`; break;
                }

                // Market classification — all 4 candidates (national + 3 states) breach the screen.
                const miss = Math.abs(d.markets - this.CANDIDATE_MARKETS);
                rigourDelta += (4 - miss * 2);
                if (d.markets <= 1) { errorDelta += 6; defenceDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r2_underflag`; }
                else if (d.markets === this.CANDIDATE_MARKETS) { defenceDelta += 4; }

                // A market definition never tested in R1 undermines the whole concentration table.
                if (!tested) { defenceDelta -= 6; rigourDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r2_untested`; }

                if (d.screen === `trigger` && d.theory === `both` && coachKey === `coach_default`) coachKey = `coach_r2_good`;

                summaryKey = (d.screen === `trigger` && d.theory === `both` && d.markets >= 3) ? `sum_r2_good` :
                             (d.screen === `verdict` ? `sum_r2_verdict` : `sum_r2_weak`);
            } else if (round === 3) {
                // Common Error 3: crediting unverified synergies; the effects estimate decides.
                days = 25;
                const div = d.diversion;                 // diversion ratio (%) for UPP/GUPPI

                // UPP/GUPPI: predicted unilateral rise scales with diversion (a ~40% diversion
                // on these margins maps to the 6–11% band in the reference card).
                const predicted = Math.round((2 + div * 0.18) * 10) / 10;   // ≈ 6.2% at 40%, ≈ 12.8% at 60%
                ds.predictedRise = predicted;

                // Reward landing inside the evidenced 6–11% band; punish lowballing/overshooting.
                if (predicted >= 6 && predicted <= 11) { rigourDelta += 10; defenceDelta += 8; }
                else if (predicted < 6) { rigourDelta -= 6; errorDelta += 8; coachKey = `coach_r3_lowball`; }
                else { rigourDelta -= 4; defenceDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_overshoot`; }

                // Efficiencies defence — three-part standard + pass-through.
                let credited = 0;
                switch (d.synergy) {
                    case `discipline`:
                        // Credit ~half as merger-specific & verifiable, then only the passed-through share.
                        credited = Math.round(this.SYNERGY_CLAIM * 0.5 * (d.passthrough / 100));
                        rigourDelta += 12; defenceDelta += 10; welfareDelta += 6; coachKey = `coach_r3_discipline`;
                        break;
                    case `full`:
                        // Treats the slide as fact — Common Error 3.
                        credited = this.SYNERGY_CLAIM;
                        rigourDelta -= 10; defenceDelta -= 10; errorDelta += 12; welfareDelta -= 6; coachKey = `coach_r3_full`;
                        break;
                    case `zero`:
                        // Reflexive zero ignores genuine merger-specific savings — also a discipline failure.
                        credited = 0;
                        rigourDelta -= 4; defenceDelta -= 4; errorDelta += 4; coachKey = `coach_r3_zero`;
                        break;
                }
                ds.creditedSynergy = credited;

                // Net welfare: predicted rise hurts; credited (passed-through) synergy offsets a little.
                const netHarm = (predicted - 6) * 1.5 - (credited / 200);
                welfareDelta -= Math.round(netHarm);

                if (d.synergy === `full` && credited >= this.SYNERGY_CLAIM) errorDelta += 4;

                summaryKey = (d.synergy === `discipline` && predicted >= 6 && predicted <= 11) ? `sum_r3_good` :
                             (d.synergy === `full` ? `sum_r3_full` : `sum_r3_weak`);
            } else if (round === 4) {
                // Common Errors 4 & 5: behavioural default & disproportionate prohibition.
                days = 22;
                ds.finalReco = d.reco;
                const harmReal = ds.predictedRise >= 6;   // an evidenced harm exists in the overlap

                // The recommendation, scored against what the evidence supports.
                if (d.reco === `remedy`) {
                    if (d.remedy === `structural`) {
                        // Targeted divestiture restores competition in the overlap, lets the rest proceed.
                        welfareDelta += 18; defenceDelta += 14; errorDelta -= 18; coachKey = `coach_r4_structural`;
                    } else if (d.remedy === `behavioural`) {
                        // Price cap is hard to monitor across thousands of SKUs — Common Error 4.
                        welfareDelta += 6; defenceDelta -= 4; errorDelta -= 4; coachKey = `coach_r4_behavioural`;
                    }
                } else if (d.reco === `block`) {
                    // Prohibition cures the harm but is disproportionate when a divestiture would do —
                    // destroys real synergies and invites a successful NCLAT appeal (Common Error 5).
                    welfareDelta += 8; defenceDelta -= 8; errorDelta += 10; coachKey = `coach_r4_block`;
                } else { // clear
                    if (harmReal) {
                        // Clearing a deal with an evidenced 6–11% rise on a staple — the Type II error.
                        welfareDelta -= 16; defenceDelta -= 10; errorDelta += 16; coachKey = `coach_r4_clear`;
                    } else {
                        welfareDelta += 4; defenceDelta += 2;
                    }
                }

                // Error-weighting philosophy.
                switch (d.error) {
                    case `proportion`: defenceDelta += 10; errorDelta -= 10; rigourDelta += 4; break;
                    case `typeii`: errorDelta += 4; if (d.reco === `block`) errorDelta += 4; break;
                    case `typei`: errorDelta += 4; if (d.reco === `clear`) errorDelta += 6; break;
                }

                // Conviction = can you defend the order, on time, on the evidence?
                if (d.conviction >= 60) { defenceDelta += 5; }
                else if (d.conviction <= 25) { defenceDelta -= 5; errorDelta += 4; }

                if (d.reco === `remedy` && d.remedy === `structural` && d.error === `proportion`) coachKey = `coach_r4_best`;

                summaryKey = (d.reco === `remedy` && d.remedy === `structural`) ? `sum_r4_good` :
                             (d.reco === `block` ? `sum_r4_block` :
                             (d.reco === `clear` ? `sum_r4_clear` : `sum_r4_weak`));
            }

            // Statutory clock — every round consumes working days toward the 210 limit.
            ds.daysUsed = Math.min(this.STATUTORY_LIMIT, ds.daysUsed + days);

            // Apply deltas, clamped. KPIs start low for headroom; error 0–100 (lower better).
            ds.welfare = Math.max(0, Math.min(100, Math.round(ds.welfare + welfareDelta)));
            ds.rigour = Math.max(0, Math.min(100, Math.round(ds.rigour + rigourDelta)));
            ds.defence = Math.max(0, Math.min(100, Math.round(ds.defence + defenceDelta)));
            ds.error = Math.max(0, Math.min(100, Math.round(ds.error + errorDelta)));

            ds.welfareHistory.push(ds.welfare);
            ds.rigourHistory.push(ds.rigour);
            ds.defenceHistory.push(ds.defence);
            ds.errorHistory.push(ds.error);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                welfare: ds.welfare,
                welfareDelta: Math.round(welfareDelta),
                rigour: ds.rigour,
                rigourDelta: Math.round(rigourDelta),
                defence: ds.defence,
                defenceDelta: Math.round(defenceDelta),
                error: ds.error,
                errorDelta: Math.round(errorDelta),
                daysUsed: ds.daysUsed,
                predictedRise: ds.predictedRise,
                creditedSynergy: ds.creditedSynergy,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

