        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const welfare = Math.round(ds.welfare);
            const rigour = Math.round(ds.rigour);
            const defence = Math.round(ds.defence);
            const error = Math.round(ds.error);
            const composite = Math.round(
                welfare * 0.30 + rigour * 0.24 + defence * 0.28 + (100 - error) * 0.18
            );
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.met;
            const badge = met
                ? `<span class="ccisim-cm-badge ccisim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="ccisim-cm-badge ccisim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.overturned) failBadge += ` <span class="ccisim-cm-badge ccisim-cm-no">` + T(`cm_overturned`) + `</span>`;
            if (s.marketTested === false) failBadge += ` <span class="ccisim-cm-badge ccisim-cm-no">` + T(`cm_untested`) + `</span>`;
            if (s.finalReco === `clear` && s.predictedRise >= 6) failBadge += ` <span class="ccisim-cm-badge ccisim-cm-no">` + T(`cm_typeii`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="ccisim-cm-metric"><span class="ccisim-cm-mv">` + Math.round(s.welfare || 0) + `</span><span class="ccisim-cm-ml">` + T(`cm_m_welfare`) + `</span></div>`
                + `<div class="ccisim-cm-metric"><span class="ccisim-cm-mv">` + Math.round(s.rigour || 0) + `</span><span class="ccisim-cm-ml">` + T(`cm_m_rigour`) + `</span></div>`
                + `<div class="ccisim-cm-metric"><span class="ccisim-cm-mv">` + Math.round(s.defence || 0) + `</span><span class="ccisim-cm-ml">` + T(`cm_m_defence`) + `</span></div>`
                + `<div class="ccisim-cm-metric"><span class="ccisim-cm-mv">` + Math.round(s.error || 0) + `</span><span class="ccisim-cm-ml">` + T(`cm_m_error`) + `</span></div>`;
            return ``
                + `<div class="ccisim-completion">`
                +   `<div class="ccisim-cm-head">`
                +     `<div class="ccisim-cm-score">` + score + `<span class="ccisim-cm-score-max">/100</span></div>`
                +     `<div class="ccisim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="ccisim-cm-metrics">` + metrics + `</div>`
                +   `<div class="ccisim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="ccisim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const welfare = Math.round(ds.welfare);
            const rigour = Math.round(ds.rigour);
            const defence = Math.round(ds.defence);
            const error = Math.round(ds.error);

            // Composite: welfare protection, rigour, defensibility, and low error.
            const composite = this._composite(ds);

            const onTime = ds.daysUsed <= this.STATUTORY_LIMIT;
            const rigorous = rigour >= 60;
            const defensible = defence >= 60 && error <= 35;
            const protective = welfare >= 60;
            const overturned = defence < 40 || error >= 65;

            let performanceKey = `grade_vulnerable`;
            if (protective && rigorous && defensible && composite >= 75) performanceKey = `grade_upheld`;
            else if (defensible && rigorous) performanceKey = `grade_defensible`;
            else if (overturned) performanceKey = `grade_overturned`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (protective && rigorous && defensible) insights.push(window.mySimulation.t(`insight_upheld`));
            else if (overturned) insights.push(window.mySimulation.t(`insight_overturned`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!ds.marketTested) insights.push(window.mySimulation.t(`insight_untested`));
            if (ds.finalReco === `clear` && ds.predictedRise >= 6) insights.push(window.mySimulation.t(`insight_typeii`));
            if (ds.finalReco === `block`) insights.push(window.mySimulation.t(`insight_typei`));
            if (ds.finalReco === `remedy`) insights.push(window.mySimulation.t(`insight_remedy`));
            if (!onTime) insights.push(window.mySimulation.t(`insight_clock`));

            return {
                welfare: welfare,
                rigour: rigour,
                defence: defence,
                error: error,
                daysUsed: ds.daysUsed,
                predictedRise: ds.predictedRise,
                creditedSynergy: ds.creditedSynergy,
                marketTested: ds.marketTested,
                finalReco: ds.finalReco,
                onTime: onTime,
                rigorous: rigorous,
                defensible: defensible,
                protective: protective,
                overturned: overturned,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: (protective && rigorous && defensible && composite >= 75),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (!ds.marketTested && state.currentPeriod >= 2) return window.mySimulation.t(`hint_untested`);
            if (ds.finalReco === `clear` && ds.predictedRise >= 6) return window.mySimulation.t(`hint_typeii`);
            if (ds.error >= 65) return window.mySimulation.t(`hint_error`);
            if (ds.defence < 40 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_defence`);
            if (ds.welfare >= 65 && ds.defence >= 60 && ds.error <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

